// Builds the curated icon data of @ems/icons from the installed @lucide/angular.
//
// Input:  icons.json            { "<ems-name>": "<Lucide name>" }, e.g. "filter": "Funnel"
// Output: src/generated/icons.ts  plain `LucideIconData` objects (name, size, node, aliases),
//                                 committed and regenerated by `npm run icons:build`.
//
// Why: every `Lucide<Name>` export of @lucide/angular is a full Angular component (factory, ɵcmp
// and a compiled template, about 2.8 kB each). Importing the classes only to read their static
// `.icon` data pulled all of them into the initial bundle. The data alone is a few hundred bytes
// per icon, and `LucideDynamicIcon` renders it identically.
//
// @lucide/angular ships one FESM file and no data-only entry point, so this script reads the
// `static icon = {…}` literal of each requested class from that file. The literal is pure data;
// it is evaluated in an empty VM context and validated before it is written.
import { readFile, mkdir, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);

/** @type {Record<string, string>} */
const manifest = JSON.parse(await readFile(join(root, 'icons.json'), 'utf8'));

const pkgJsonPath = require.resolve('@lucide/angular/package.json');
const pkg = JSON.parse(await readFile(pkgJsonPath, 'utf8'));
const fesm = await readFile(join(dirname(pkgJsonPath), pkg.module), 'utf8');

/**
 * Returns the object literal starting at `start` (which must be `{`), by brace matching.
 * Icon data contains no braces inside strings (path data, keys and names only), which the
 * validation below would catch anyway.
 */
function literalAt(source, start) {
  let depth = 0;
  for (let i = start; i < source.length; i++) {
    if (source[i] === '{') depth++;
    else if (source[i] === '}' && --depth === 0) return source.slice(start, i + 1);
  }
  throw new Error('Unterminated icon literal');
}

function iconData(lucideName) {
  const marker = `var Lucide${lucideName} = class Lucide${lucideName} extends LucideIconBase {`;
  const classStart = fesm.indexOf(marker);
  if (classStart === -1) {
    throw new Error(`@lucide/angular has no icon Lucide${lucideName} (check icons.json)`);
  }
  const fieldStart = fesm.indexOf('static icon = {', classStart);
  if (fieldStart === -1 || fieldStart > fesm.indexOf('static ɵfac', classStart)) {
    throw new Error(`Could not find the icon data of Lucide${lucideName}`);
  }
  const literal = literalAt(fesm, fieldStart + 'static icon = '.length);
  const data = vm.runInNewContext(`(${literal})`, Object.create(null), { timeout: 1000 });
  const valid =
    typeof data?.name === 'string' &&
    Array.isArray(data.node) &&
    data.node.every(
      (n) => Array.isArray(n) && typeof n[0] === 'string' && n[1] && typeof n[1] === 'object',
    );
  if (!valid) {
    throw new Error(`Unexpected icon data for Lucide${lucideName}`);
  }
  // Fixed key order keeps the output stable.
  return {
    name: data.name,
    ...(data.size === undefined ? {} : { size: data.size }),
    node: data.node,
    ...(data.aliases?.length ? { aliases: data.aliases } : {}),
  };
}

const entries = Object.entries(manifest).sort(([a], [b]) => a.localeCompare(b));
const body = entries
  .map(
    ([name, lucideName]) => `  ${JSON.stringify(name)}: ${JSON.stringify(iconData(lucideName))},`,
  )
  .join('\n');

const out = `// Generated by projects/icons/scripts/build-icons.mjs from @lucide/angular ${pkg.version}.
// Do not edit. Add icons to projects/icons/icons.json and run \`npm run icons:build\`.
import type { LucideIconData } from '@lucide/angular';

/** Curated Lucide icon data, keyed by EMS icon name (plain data, no component classes). */
export const EMS_ICON_DATA = {
${body}
} satisfies Readonly<Record<string, LucideIconData>>;
`;

const outDir = join(root, 'src', 'generated');
await mkdir(outDir, { recursive: true });
await writeFile(join(outDir, 'icons.ts'), out);
console.log(`icons: wrote ${entries.length} icons from @lucide/angular ${pkg.version}`);
